  letter-spacing: 0.02em;
  border: 1px solid rgba(255, 255, 255, 0.54);
  background: var(--th-id-color);
  color: rgba(255, 255, 255, 0.96);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.16);
}

#${r} .th-inline-danmu-dot {
  margin-right: 0.34em;
  color: rgba(255, 255, 255, 0.96);
  font-weight: 900;
}

#${r} .th-inline-danmu-content {
  font-weight: 700;
}

#${r} .th-inline-danmu-reaction {
  position: absolute;
  left: 0;
  top: 0;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
  background: linear-gradient(135deg, rgba(24, 24, 36, 0.9), rgba(41, 29, 53, 0.84));
  color: #fff;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.24);
  border: 1px solid rgba(255, 255, 255, 0.35);
  animation: th-inline-danmu-reaction-rise 1180ms ease-out forwards;
  pointer-events: none;
}

#${r} .th-inline-danmu-reaction.sticky {
  position: absolute;
  right: 8px;
  top: 6px;
  left: auto;
  font-size: 11px;
  padding: 2px 10px;
  border-radius: 999px;
  background: linear-gradient(135deg, rgba(255, 145, 195, 0.76), rgba(111, 157, 255, 0.78));
  color: #fff;
  animation: none;
  opacity: 0.92;
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
  box-shadow: 0 5px 14px rgba(45, 34, 72, 0.26);
  border: 1px solid rgba(255, 255, 255, 0.45);
  pointer-events: none;
  z-index: 2;
}

@keyframes th-inline-danmu-reaction-rise {
  0% {
    opacity: 0;
    transform: translate3d(var(--th-rx, 0px), var(--th-ry, 0px), 0) scale(0.9);
  }
  15% {
    opacity: 1;
    transform: translate3d(var(--th-rx, 0px), calc(var(--th-ry, 0px) - 2px), 0) scale(1);
  }
  100% {
    opacity: 0;
    transform: translate3d(var(--th-rx, 0px), calc(var(--th-ry, 0px) - 12px), 0) scale(1.02);
  }
}

@keyframes th-inline-danmu-l2r {
  0% {
    transform: translate3d(var(--th-start-x), var(--th-y), 0);
  }
  100% {
    transform: translate3d(var(--th-end-x), var(--th-y), 0);
  }
}

@keyframes th-inline-danmu-status-breath {
  0% {
    transform: scale(1);
    box-shadow: 0 0 0 0 rgba(255, 77, 109, 0.66);
  }
  70% {
    transform: scale(1.04);
    box-shadow: 0 0 0 8px rgba(255, 77, 109, 0);
  }
  100% {
    transform: scale(1);
    box-shadow: 0 0 0 0 rgba(255, 77, 109, 0);
  }
}
